import java.io.*;

public class Main {
    static Scanner input = new Scanner(System.in);
    static long[][][] cacheDP;
    static int MOD = 998244353;

    public static void main(String[] args) {
        int T = 1;
        while (T > 0) {
            String s = input.nextLine();
            char[] A = s.toCharArray();
            if (A.length == 1 && A[0] == '0') {
                System.out.println("1");
                return;
            }
            if (A[0] == '0') {
                System.out.println("0");
                return;
            }
            if (A.length == 1 && (A[0] == 'X' || A[0] == '_')) {
                System.out.println("1");
                return;
            }
            cacheDP = new long[A.length + 1][25][11];
            for (long[][] layer : cacheDP) {
                for (long[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }
            System.out.println(solveDP(A, 0, 0, 10));
            T--;
        }
        input.close();
    }

    static long solveDP(char[] A, int index, int prev, int v) {
        if (index == A.length) {
            return prev == 0 ? 1 : 0;
        }
        if (cacheDP[index][prev][v] != -1) {
            return cacheDP[index][prev][v];
        }
        long res = 0;
        if (A[index] == '_') {
            for (int j = 0; j < 10; j++) {
                if (index == 0 && j == 0) continue;
                int newPrev = (prev * 10 + j) % 25;
                res += solveDP(A, index + 1, newPrev, v);
            }
        } else if (A[index] == 'X') {
            if (v != 10) {
                res += solveDP(A, index + 1, (prev * 10 + v) % 25, v);
            } else {
                for (int j = 0; j < 10; j++) {
                    if (index == 0 && j == 0) continue;
                    int newPrev = (prev * 10 + j) % 25;
                    res += solveDP(A, index + 1, newPrev, j);
                }
            }
        } else {
            int digit = A[index] - '0';
            res += solveDP(A, index + 1, (prev * 10 + digit) % 25, v);
        }
        return cacheDP[index][prev][v] = res;
    }
}
